95	  DFSStripedInputStream(DFSClient dfsClient, String src,
96	      boolean verifyChecksum, ErasureCodingPolicy ecPolicy,
97	      LocatedBlocks locatedBlocks) throws IOException {
98	    super(dfsClient, src, verifyChecksum, locatedBlocks);
99	
100	    this.readStatistics.setBlockType(BlockType.STRIPED);
101	    assert ecPolicy != null;
102	    this.ecPolicy = ecPolicy;
103	    this.cellSize = ecPolicy.getCellSize();
104	    dataBlkNum = (short) ecPolicy.getNumDataUnits();
105	    parityBlkNum = (short) ecPolicy.getNumParityUnits();
106	    groupSize = dataBlkNum + parityBlkNum;
107	    blockReaders = new BlockReaderInfo[groupSize];
108	    curStripeRange = new StripeRange(0, 0);
109	    ErasureCoderOptions coderOptions = new ErasureCoderOptions(
110	        dataBlkNum, parityBlkNum);
111	    decoder = CodecUtil.createRawDecoder(dfsClient.getConfiguration(),
112	        ecPolicy.getCodecName(), coderOptions);
113	    DFSClient.LOG.debug("Creating an striped input stream for file {}", src);
114	  }
