120	  private void resetCurStripeBuffer(boolean shouldAllocateBuf) {
121	    if (shouldAllocateBuf && curStripeBuf == null) {
122	      curStripeBuf = BUFFER_POOL.getBuffer(useDirectBuffer(),
123	          cellSize * dataBlkNum);
124	    }
125	    if (curStripeBuf != null) {
126	      curStripeBuf.clear();
127	    }
128	    curStripeRange = new StripeRange(0, 0);
129	  }
