151	  /**
152	   * When seeking into a new block group, create blockReader for each internal
153	   * block in the group.
154	   */
155	  @VisibleForTesting
156	  synchronized void blockSeekTo(long target) throws IOException {
157	    if (target >= getFileLength()) {
158	      throw new IOException("Attempted to read past end of file");
159	    }
160	
161	    maybeRegisterBlockRefresh();
162	
163	    // Will be getting a new BlockReader.
164	    closeCurrentBlockReaders();
165	
166	    // Compute desired striped block group
167	    LocatedStripedBlock targetBlockGroup = getBlockGroupAt(target);
168	    // Update current position
169	    this.pos = target;
170	    this.blockEnd = targetBlockGroup.getStartOffset() +
171	        targetBlockGroup.getBlockSize() - 1;
172	    currentLocatedBlock = targetBlockGroup;
173	  }
