175	  @Override
176	  public synchronized void close() throws IOException {
177	    try {
178	      super.close();
179	    } finally {
180	      if (curStripeBuf != null) {
181	        BUFFER_POOL.putBuffer(curStripeBuf);
182	        curStripeBuf = null;
183	      }
184	      if (parityBuf != null) {
185	        BUFFER_POOL.putBuffer(parityBuf);
186	        parityBuf = null;
187	      }
188	      if (decoder != null) {
189	        decoder.release();
190	        decoder = null;
191	      }
192	    }
193	  }
