195	  /**
196	   * Extend the super method with the logic of switching between cells.
197	   * When reaching the end of a cell, proceed to the next cell and read it
198	   * with the next blockReader.
199	   */
200	  @Override
201	  protected void closeCurrentBlockReaders() {
202	    resetCurStripeBuffer(false);
203	    if (blockReaders ==  null || blockReaders.length == 0) {
204	      return;
205	    }
206	    for (int i = 0; i < groupSize; i++) {
207	      closeReader(blockReaders[i]);
208	      blockReaders[i] = null;
209	    }
210	    blockEnd = -1;
211	  }
