213	  protected void closeReader(BlockReaderInfo readerInfo) {
214	    if (readerInfo != null) {
215	      if (readerInfo.reader != null) {
216	        try {
217	          readerInfo.reader.close();
218	        } catch (Throwable ignored) {
219	        }
220	      }
221	      readerInfo.skip();
222	    }
223	  }
