323	   * Update read statistics. Note that this has to be done on the thread that
324	   * initiates the read, rather than inside each async thread, for
325	   * {@link org.apache.hadoop.fs.FileSystem.Statistics} to work correctly with
326	   * its ThreadLocal.
327	   *
328	   * @param stats striped read stats
329	   */
330	  void updateReadStats(final StripedBlockUtil.BlockReadStats stats) {
331	    if (stats == null) {
332	      return;
333	    }
334	    updateReadStatistics(readStatistics, stats.getBytesRead(),
335	        stats.isShortCircuit(), stats.getNetworkDistance());
