342	  /**
343	   * Seek to a new arbitrary location.
344	   */
345	  @Override
346	  public synchronized void seek(long targetPos) throws IOException {
347	    if (targetPos > getFileLength()) {
348	      throw new EOFException("Cannot seek after EOF");
349	    }
350	    if (targetPos < 0) {
351	      throw new EOFException("Cannot seek to negative offset");
352	    }
353	    if (closed.get()) {
354	      throw new IOException("Stream is closed!");
355	    }
356	    if (targetPos <= blockEnd) {
357	      final long targetOffsetInBlk = getOffsetInBlockGroup(targetPos);
358	      if (curStripeRange.include(targetOffsetInBlk)) {
359	        int bufOffset = getStripedBufOffset(targetOffsetInBlk);
360	        curStripeBuf.position(bufOffset);
361	        pos = targetPos;
362	        return;
363	      }
364	    }
365	    pos = targetPos;
366	    blockEnd = -1;
367	  }
