369	  private int getStripedBufOffset(long offsetInBlockGroup) {
370	    final long stripeLen = cellSize * dataBlkNum;
371	    // compute the position in the curStripeBuf based on "pos"
372	    return (int) (offsetInBlockGroup % stripeLen);
373	  }
