381	  @Override
382	  protected synchronized int readWithStrategy(ReaderStrategy strategy)
383	      throws IOException {
384	    dfsClient.checkOpen();
385	    if (closed.get()) {
386	      throw new IOException("Stream closed");
387	    }
388	
389	    int len = strategy.getTargetLength();
390	    CorruptedBlocks corruptedBlocks = new CorruptedBlocks();
391	    if (pos < getFileLength()) {
392	      try {
393	        if (pos > blockEnd) {
394	          blockSeekTo(pos);
395	        }
396	        int realLen = (int) Math.min(len, (blockEnd - pos + 1L));
397	        synchronized (infoLock) {
398	          if (locatedBlocks.isLastBlockComplete()) {
399	            realLen = (int) Math.min(realLen,
400	                locatedBlocks.getFileLength() - pos);
401	          }
402	        }
403	
404	        /** Number of bytes already read into buffer */
405	        int result = 0;
406	        while (result < realLen) {
407	          if (!curStripeRange.include(getOffsetInBlockGroup())) {
408	            readOneStripe(corruptedBlocks);
409	          }
410	          int ret = copyToTargetBuf(strategy, realLen - result);
411	          result += ret;
412	          pos += ret;
413	        }
414	        return result;
415	      } finally {
416	        // Check if need to report block replicas corruption either read
417	        // was successful or ChecksumException occurred.
418	        reportCheckSumFailure(corruptedBlocks, getCurrentBlockLocationsLength(),
419	            true);
420	      }
421	    }
422	    return -1;
423	  }
