425	  /**
426	   * Copy the data from {@link #curStripeBuf} into the given buffer.
427	   * @param strategy the ReaderStrategy containing the given buffer
428	   * @param length target length
429	   * @return number of bytes copied
430	   */
431	  private int copyToTargetBuf(ReaderStrategy strategy, int length) {
432	    final long offsetInBlk = getOffsetInBlockGroup();
433	    int bufOffset = getStripedBufOffset(offsetInBlk);
434	    curStripeBuf.position(bufOffset);
435	    return strategy.readFromBuffer(curStripeBuf,
436	        Math.min(length, curStripeBuf.remaining()));
437	  }
