439	  /**
440	   * The super method {@link DFSInputStream#refreshLocatedBlock} refreshes
441	   * cached LocatedBlock by executing {@link DFSInputStream#getBlockAt} again.
442	   * This method extends the logic by first remembering the index of the
443	   * internal block, and re-parsing the refreshed block group with the same
444	   * index.
445	   */
446	  @Override
447	  protected LocatedBlock refreshLocatedBlock(LocatedBlock block)
448	      throws IOException {
449	    int idx = StripedBlockUtil.getBlockIndex(block.getBlock().getLocalBlock());
450	    LocatedBlock lb = getBlockGroupAt(block.getStartOffset());
451	    // If indexing information is returned, iterate through the index array
452	    // to find the entry for position idx in the group
453	    LocatedStripedBlock lsb = (LocatedStripedBlock) lb;
454	    int i = 0;
455	    for (; i < lsb.getBlockIndices().length; i++) {
456	      if (lsb.getBlockIndices()[i] == idx) {
457	        break;
458	      }
459	    }
460	    DFSClient.LOG.debug("refreshLocatedBlock for striped blocks, offset={}." +
461	        " Obtained block {}, idx={}", block.getStartOffset(), lb, idx);
462	    return StripedBlockUtil.constructInternalBlock(
463	        lsb, i, cellSize, dataBlkNum, idx);
464	  }
