466	  private LocatedStripedBlock getBlockGroupAt(long offset) throws IOException {
467	    LocatedBlock lb = super.getBlockAt(offset);
468	    assert lb instanceof LocatedStripedBlock : "NameNode" +
469	        " should return a LocatedStripedBlock for a striped file";
470	    return (LocatedStripedBlock)lb;
471	  }
