473	  /**
474	   * Real implementation of pread.
475	   */
476	  @Override
477	  protected void fetchBlockByteRange(LocatedBlock block, long start,
478	      long end, ByteBuffer buf, CorruptedBlocks corruptedBlocks)
479	      throws IOException {
480	    // Refresh the striped block group
481	    LocatedStripedBlock blockGroup = getBlockGroupAt(block.getStartOffset());
482	
483	    AlignedStripe[] stripes = StripedBlockUtil.divideByteRangeIntoStripes(
484	        ecPolicy, cellSize, blockGroup, start, end, buf);
485	    final LocatedBlock[] blks = StripedBlockUtil.parseStripedBlockGroup(
486	        blockGroup, cellSize, dataBlkNum, parityBlkNum);
487	    final BlockReaderInfo[] preaderInfos = new BlockReaderInfo[groupSize];
488	    try {
489	      for (AlignedStripe stripe : stripes) {
490	        // Parse group to get chosen DN location
491	        StripeReader preader = new PositionStripeReader(stripe, ecPolicy, blks,
492	            preaderInfos, corruptedBlocks, decoder, this);
493	        try {
494	          preader.readStripe();
495	        } finally {
496	          preader.close();
497	        }
498	      }
499	      buf.position(buf.position() + (int)(end - start + 1));
500	    } finally {
501	      for (BlockReaderInfo preaderInfo : preaderInfos) {
502	        closeReader(preaderInfo);
503	      }
504	    }
505	  }
