507	  @Override
508	  protected void reportLostBlock(LocatedBlock lostBlock,
509	      Collection<DatanodeInfo> ignoredNodes) {
510	    DatanodeInfo[] nodes = lostBlock.getLocations();
511	    if (nodes != null && nodes.length > 0) {
512	      List<String> dnUUIDs = new ArrayList<>();
513	      for (DatanodeInfo node : nodes) {
514	        dnUUIDs.add(node.getDatanodeUuid());
515	      }
516	      if (!warnedNodes.containsAll(dnUUIDs)) {
517	        DFSClient.LOG.warn(Arrays.toString(nodes) + " are unavailable and " +
518	            "all striping blocks on them are lost. " +
519	            "IgnoredNodes = {}", ignoredNodes);
520	        warnedNodes.addAll(dnUUIDs);
521	      }
522	    } else {
523	      super.reportLostBlock(lostBlock, ignoredNodes);
524	    }
525	  }
